{
  "schemaVersion": 1,
  "id": "python-kit",
  "version": "0.1.0",
  "description": "Python 编写指南和任务独立的 Python 执行环境",
  "host": { "os": ["linux"], "arch": ["x64", "arm64"] },
  "preparation": { "granularity": "capability" },
  "permissions": { "filesystem": "package-state-and-workspace", "network": false },
  "provides": [
    {
      "id": "python.author", "interfaceVersion": 1, "kind": "guidance",
      "description": "Python 编写与测试方法", "instructions": "AUTHOR.md", "tools": []
    },
    {
      "id": "python.execute", "interfaceVersion": 1, "kind": "tools",
      "description": "在任务独立的 Python 虚拟环境执行代码", "instructions": "EXECUTE.md",
      "tools": [{
        "name": "python_run", "description": "Run Python code in the prepared task venv. No third-party dependencies are installed.",
        "exposure": "on_activation",
        "parameters": { "type": "object", "properties": { "code": { "type": "string" } }, "required": ["code"], "additionalProperties": false }
      }]
    }
  ],
  "requires": [{ "id": "shell.execute", "interfaceVersion": 1, "phase": "prepare", "for": ["python.execute"] }],
  "lifecycle": { "runtime": "node", "entry": "worker.mjs" }
}

import { access, rm } from 'node:fs/promises';
import { join } from 'node:path';
import { spawnSync } from 'node:child_process';
let input = '';
for await (const chunk of process.stdin) input += chunk;
const request = JSON.parse(input);
const interpreter = join(request.taskDir, 'venv', 'bin', 'python');
const execute = (program, args) => spawnSync(program, args, {
  cwd: request.workspace, env: process.env, encoding: 'utf8', timeout: 15000, maxBuffer: 32768,
});
const ready = (passed, name, resources) => ({ status: passed ? 'ready' : 'not_ready', checks: [{ name, passed }], ...(resources ? { resources } : {}) });
let response;
switch (request.operation) {
  case 'check': {
    const capabilities = {};
    for (const id of request.requested) {
      if (id === 'python.author') capabilities[id] = ready(true, 'bundled_guidance');
      else if (id === 'python.execute') {
        const exists = await access(interpreter).then(() => true, () => false);
        const runnable = exists && execute(interpreter, ['-c', 'import sys; assert sys.prefix != sys.base_prefix']).status === 0;
        const status = ready(runnable, 'task_venv_executes', runnable ? { interpreter } : undefined);
        if (!runnable && execute('python3', ['--version']).status !== 0) {
          status.status = 'blocked'; status.reason = 'Host Python 3 is missing; this package does not download runtimes yet';
        }
        capabilities[id] = status;
      } else throw new Error(`Unknown capability ${id}`);
    }
    response = { capabilities }; break;
  }
  case 'prepare': {
    if (request.requested.includes('python.execute')) {
      const shell = request.dependencies.find(d => d.id === 'shell.execute' && d.phase === 'prepare')?.resources.shell;
      if (typeof shell !== 'string') throw new Error('Missing prepared shell dependency');
      // The package, not the manager, chooses this preparation strategy.
      const found = execute(shell, ['-c', 'command -v python3']);
      if (found.status !== 0) throw new Error('Python 3 is unavailable');
      const prepared = execute(found.stdout.trim(), ['-m', 'venv', '--without-pip', join(request.taskDir, 'venv')]);
      if (prepared.status !== 0) throw new Error(`venv preparation failed: ${prepared.stderr}`);
    }
    response = { prepared: request.requested }; break;
  }
  case 'invoke': {
    if (request.tool !== 'python_run' || !request.requested.includes('python.execute')) throw new Error('Unknown tool');
    const output = execute(interpreter, ['-c', request.args.code]);
    if (output.error || output.status !== 0) throw new Error(`Python failed: ${output.error?.message ?? output.stderr}`);
    response = { exitCode: output.status, stdout: output.stdout, stderr: output.stderr }; break;
  }
  case 'release':
    await rm(request.taskDir, { recursive: true, force: true }); response = { released: true }; break;
  default: throw new Error('Unknown operation');
}
process.stdout.write(JSON.stringify(response));
